slog.Info("running checks against repository", "repository", repository)
	client, err := config.GetMatchingGitClient(repository)
	if err != nil {
		return errors.Wrap(err, "failed to create git client")
	}

	enabledChecks := config.GetNeededObservers()

	checker := observe.NewParallelObserver(
		enabledChecks...,
	)

	checkResults, err := checker.RunObservers(ctx, client, repository, observe.AdditionalInputData{
		CosignAttestClient: common.NewCosignAttestationClient(),
	})
	if err != nil {
		return errors.Wrap(err, "failed to run checks")
	}

	badgesResult := badges.Eval(repository, checkResults, config.RuntimeConfig.Badges)

	// SaveToDatabase(repository, badgesResult) // optional..

	// transform the checkResults
	sarif, err := transformer.ConvertBadgeResultsToSarif(repository, client.IsRepoMirrored(ctx, repository), badgesResult)
	if err != nil {
		return errors.Wrap(err, "failed to convert to sarif")
	}

	if output != "" {
		err = os.WriteFile(output, sarif, 0600)
		if err != nil {
			return errors.Wrap(err, "failed to save sarif report to filesystem")
		}
	}

	printBadgeTable(badgesResult)

	return nil
}

func printBadgeTable(badgesResult []badges.Badge) {
	for _, badge := range badgesResult {
		badgeGrantedStr, badgeGrantedColor := badgeGrantedToStrAndColor(badge.BadgeGranted)

		t := table.NewWriter()
		t.SetOutputMirror(os.Stdout)
		t.SetTitle(fmt.Sprintf("BadgeReport for %s (%s) - %s", badge.BadgeName, badge.BadgeLevel, badgeGrantedColor.Sprint(badgeGrantedStr)))
		t.AppendHeader(table.Row{"Check", "Status", "Description", "Evidence"})

		for _, criteria := range badge.BadgeExplanation.Criteria {
			fgColor := statusToColor(criteria.Status)
			t.AppendRow(table.Row{
				strings.Split(criteria.RuleID, ":")[0],
				fgColor.Sprint(criteria.Status),
				text.WrapSoft(criteria.Description, tableColumnWidth),
				text.WrapSoft(criteria.Evidence, tableColumnWidth),
			})
		}

		t.SetColumnConfigs([]table.ColumnConfig{
			{Number: 1, WidthMin: 16, WidthMax: 16},
			{Number: 2, Align: text.AlignCenter, AlignHeader: text.AlignCenter, WidthMin: 14, WidthMax: 14},
			{Number: 3, WidthMin: tableColumnWidth, WidthMax: tableColumnWidth},
			{Number: 4, WidthMin: tableColumnWidth, WidthMax: tableColumnWidth},
		})
		t.SetStyle(table.StyleLight)
		// t.SetStyle(table.StyleColoredBright)
		t.Style().Options.SeparateRows = true

		t.Render()
	}
}

func badgeGrantedToStrAndColor(granted bool) (string, text.Color) {
	badgeGrantedStr := "Not Granted"
	badgeGrantedColor := text.FgRed
	if granted {
		badgeGrantedStr = "Granted"
		badgeGrantedColor = text.FgGreen
	}
	return badgeGrantedStr, badgeGrantedColor
}

func statusToColor(status badges.Status) text.Color {
	// same color logik as in: https://gitlab.opencode.de/open-code/badgebackend/gitlab-profile/-/blob/main/src/components/ResultTable.tsx#L174
	switch status {
	case badges.StatusPass:
		return text.FgGreen
	case badges.StatusMissingData, badges.StatusTechnicalFailure:
		return text.FgWhite
	default:
		return text.FgRed
	}
}

func SaveToDatabase(projectURL string, hasPublicCodeYaml *bool, badgesResult []badges.Badge) error {
	// save the results to the database
	model, err := transformer.ConvertToDatabaseModel(projectURL, hasPublicCodeYaml, badgesResult)
	if err != nil {
		return errors.New(fmt.Sprintf("failed to convert to database model: %v - repositoryUrl: %s", err, projectURL))
	}

	err = db.SaveReport(model, runDate)
	if err != nil {
		return errors.New(fmt.Sprintf("failed to save report to database: %v - repositoryUrl: %s", err, projectURL))
	}
	return nil
}

